    REASON_PAIR_UNDETERMINED_SKIPPED,
)


def jaccard_distance(left: set[str], right: set[str]) -> float:
    union = left | right
    if not union:
        return 0.0
    return 1.0 - (len(left & right) / len(union))


def _clip(value: float) -> float:
    return max(0.0, min(1.0, value))


def _constraint_sets(result: EvaluatorResult) -> tuple[set[str], set[str]]:
    satisfied: set[str] = set()
    violated: set[str] = set()
    for item in result.constraints_applied:
        if item.status is ConstraintStatus.SATISFIED:
            satisfied.add(item.constraint_id)
        elif item.status is ConstraintStatus.VIOLATED:
            violated.add(item.constraint_id)
    return satisfied, violated


def pairwise_delta(
    left: EvaluatorResult,
    right: EvaluatorResult,
    config: EngineConfig,
) -> PairwiseDisagreement:
    codes: list[str] = []
    if left.verdict is Verdict.UNDETERMINED and right.verdict is Verdict.UNDETERMINED:
        return PairwiseDisagreement(
            pair=EvaluatorPair(left=left.evaluator, right=right.evaluator),
            delta=0.0,
            components=ConflictComponent(),
            reason_codes=[REASON_PAIR_BOTH_UNDETERMINED],
        )

    pi = verdict_polarity(left.verdict)
    pj = verdict_polarity(right.verdict)
    if pi is None or pj is None:
        c_conclusion = 0.0
        codes.append(REASON_PAIR_UNDETERMINED_SKIPPED)
    else:
        c_conclusion = 0.5 * abs(pi - pj)

    s_i, v_i = _constraint_sets(left)
    s_j, v_j = _constraint_sets(right)
    inverted = (s_i & v_j) | (s_j & v_i)
    applied = s_i | s_j | v_i | v_j
    c_constraint = 0.0 if not applied else len(inverted) / len(applied)
    if inverted:
        codes.append(REASON_INVERTED_CONSTRAINT)

    e_plus_i, e_minus_i = set(left.supporting_evidence_ids), set(left.contradicting_evidence_ids)
    e_plus_j, e_minus_j = set(right.supporting_evidence_ids), set(right.contradicting_evidence_ids)
    inv_e = (e_plus_i & e_minus_j) | (e_plus_j & e_minus_i)
    e_union = e_plus_i | e_plus_j | e_minus_i | e_minus_j
    c_evidence = _clip(
        0.6 * (len(inv_e) / max(1, len(e_union))) + 0.4 * jaccard_distance(e_plus_i, e_plus_j)
    )
    if inv_e:
        codes.append(REASON_INVERTED_EVIDENCE)

    pred_i = {a.predicate: a.polarity for a in left.assumptions}
    pred_j = {a.predicate: a.polarity for a in right.assumptions}
    shared = set(pred_i) & set(pred_j)
    if not shared:
        c_assumption = 0.0
    else:
        flips = [1.0 if pred_i[p] != pred_j[p] else 0.0 for p in shared]
        c_assumption = sum(flips) / len(flips)
        if any(flips):
            codes.append(REASON_ASSUMPTION_FLIP)

    c_premise = jaccard_distance(set(left.premise_ids), set(right.premise_ids))
    weights = config.contradiction
    delta = (
        weights.conclusion * c_conclusion
        + weights.constraint * c_constraint
        + weights.evidence * c_evidence
        + weights.assumption * c_assumption
        + weights.premise * c_premise
    )
    return PairwiseDisagreement(
        pair=EvaluatorPair(left=left.evaluator, right=right.evaluator),
        delta=_clip(delta),
        components=ConflictComponent(
            conclusion_conflict=_clip(c_conclusion),
            evidence_conflict=_clip(c_evidence),
            premise_conflict=_clip(c_premise),
            constraint_conflict=_clip(c_constraint),
            assumption_conflict=_clip(c_assumption),
        ),
        reason_codes=codes,
    )


def contradiction_matrix(
    results: dict[str, EvaluatorResult],
    config: EngineConfig,
) -> tuple[list[PairwiseDisagreement], float]:
    names = list(results)
    pairs: list[PairwiseDisagreement] = []
    deltas: list[float] = []
    for i, a in enumerate(names):
        for b in names[i + 1 :]:
            left, right = results[a], results[b]
            item = pairwise_delta(left, right, config)
            pairs.append(item)
            both_undetermined = (
                left.verdict is Verdict.UNDETERMINED and right.verdict is Verdict.UNDETERMINED
            )
            if not both_undetermined:
                deltas.append(item.delta)
    delta_max = max(deltas) if deltas else 0.0
    return pairs, delta_max


def assumption_partition(
    results: dict[str, EvaluatorResult],
) -> tuple[list[AssumptionAtom], list[AssumptionAtom]]:
    determined = {
        name: res
        for name, res in results.items()
        if res.verdict is not Verdict.UNDETERMINED
    }
    by_pred: dict[str, list[AssumptionAtom]] = defaultdict(list)
    for res in determined.values():
        for atom in res.assumptions:
            by_pred[atom.predicate].append(atom)
    shared: list[AssumptionAtom] = []
    conflicting: list[AssumptionAtom] = []
    for predicate, atoms in by_pred.items():
        if len(atoms) < 2:
            continue
        polarities = {a.polarity for a in atoms}
        if len(polarities) == 1:
            shared.append(atoms[0])
        else:
            conflicting.extend(atoms)
    return shared, conflicting


def critical_pairs(
    pairs: list[PairwiseDisagreement],
    tau_base: float,
) -> list[PairwiseDisagreement]:
    # Match the lattice's documented strict threshold (Delta > tau).
    return [p for p in pairs if p.delta > tau_base]

from __future__ import annotations

import time
from typing import Any, Callable

from prismthinker.config import EngineConfig
from prismthinker.core.contradiction import contradiction_matrix
from prismthinker.core.schemas import (
    CounterfactualProbe,
    FactType,
    FactValue,
    Hypothesis,
    ReasoningContext,
    Verdict,
)
from prismthinker.reason_codes import REASON_COUNTERFACTUAL_NO_SCHEMA, REASON_COUNTERFACTUAL_RESOLVED

PROBEABLE = {FactType.BOOL, FactType.INT, FactType.FLOAT, FactType.DURATION_MS, FactType.ENUM}


def _authorized_veto(results: dict) -> bool:
    return any(r.hard_veto and r.verdict is Verdict.REJECT for r in results.values())


def _is_resolving(
    delta_after: float,
    veto_after: bool,
    veto_before: bool,
    tau_base: float,
) -> bool:
    if delta_after <= tau_base and not veto_after:
        return True
    if veto_before and not veto_after:
        return True
    return False


def _candidates(spec, current: Any) -> list[Any]:
    if spec.fact_type is FactType.BOOL:
        return [not bool(current)]
    if spec.fact_type is FactType.ENUM:
        return [v for v in spec.enum_values if v != current]
    if spec.step is not None:
        step = spec.step
    elif spec.minimum is not None and spec.maximum is not None:
        step = 0.1 * (spec.maximum - spec.minimum) or 1.0
    else:
        step = 1.0
    lo = spec.minimum if spec.minimum is not None else None
    hi = spec.maximum if spec.maximum is not None else None
    values: list[Any] = []
    for k in range(1, 64):
        down = current - k * step
        up = current + k * step
        if spec.fact_type is FactType.INT:
            down, up = int(round(down)), int(round(up))
        added = False
        if lo is None or down >= lo:
            if hi is None or down <= hi:
                values.append(down)
                added = True
        if lo is None or up >= lo:
            if hi is None or up <= hi:
                values.append(up)
                added = True
        if not added:
            break
    return values


def probe_counterfactuals(
    context: ReasoningContext,
    hypothesis: Hypothesis,
    results: dict,
    delta_max: float,
    config: EngineConfig,
    run_heads: Callable[[ReasoningContext, Hypothesis], dict],
    tau: float | None = None,
) -> list[CounterfactualProbe]:
    bar = config.tau_base if tau is None else tau
    if delta_max <= bar and not _authorized_veto(results):
        return []

    mutable = []
    for key, spec in context.fact_specs.items():
        if not spec.mutable or spec.fact_type not in PROBEABLE:
            continue
        if key not in context.structured_facts:
            continue
        mutable.append(key)

    if not mutable:
        return [
            CounterfactualProbe(
                parameter_changed="",
                value_before=None,
                value_after=None,
                delta_before=delta_max,
                delta_after=delta_max,
                resolving=False,
                resolving_condition="no_mutable_facts",
                flips=[],
            )
        ]

    veto_before = _authorized_veto(results)
    prior: list[tuple[int, str]] = []
    conflicting_text = " ".join(
        a.predicate for r in results.values() for a in r.assumptions
    )
    for key in mutable:
        score = sum(1 for r in results.values() if key in r.premise_ids)
        if key in conflicting_text:
            score += 1
        prior.append((score, key))
    prior.sort(reverse=True)
    keys = [k for _, k in prior[: config.max_probe_params]]

    probes: list[CounterfactualProbe] = []
    deadline = time.perf_counter() + config.counterfactual_timeout_ms / 1000.0
    for key in keys:
        spec = context.fact_specs[key]
        before = context.structured_facts[key].value
        resolved_this_param = False
        for new_value in _candidates(spec, before):
            if len(probes) >= config.max_probes:
                break
            if time.perf_counter() > deadline:
                break
            copied = context.model_copy(deep=True)
            copied.structured_facts[key] = FactValue(
                key=key,
                value=new_value,
                unit=context.structured_facts[key].unit,
                observed_at=context.structured_facts[key].observed_at,
            )
            after_results = run_heads(copied, hypothesis)
            _, delta_after = contradiction_matrix(after_results, config)
            veto_after = _authorized_veto(after_results)
            resolving = _is_resolving(delta_after, veto_after, veto_before, bar)
            flips = [
                name
                for name, res in after_results.items()
                if name in results and res.verdict is not results[name].verdict
            ]
            condition = (
                f"If {key} changes from {before!r} to {new_value!r}, "
                f"Δ drops from {delta_max:.2f} to {delta_after:.2f}."
            )
            if resolving:
                condition = condition + " " + REASON_COUNTERFACTUAL_RESOLVED
            probes.append(
                CounterfactualProbe(
                    parameter_changed=key,
                    value_before=before,
                    value_after=new_value,
                    delta_before=delta_max,
                    delta_after=delta_after,
                    resolving=resolving,
                    resolving_condition=condition,
                    flips=flips,
                )
            )
            if resolving:
                resolved_this_param = True
                if config.stop_on_first_resolving:
                    break
            if resolved_this_param:
                break
        if len(probes) >= config.max_probes:
            break
        if time.perf_counter() > deadline:
            break

    probes.sort(key=lambda p: (not p.resolving, -(p.delta_before - p.delta_after)))
    return probes[: config.max_probes]


def no_schema_reason() -> str:
    return REASON_COUNTERFACTUAL_NO_SCHEMA

